                i += 2
            else:
                out.append(ids[i])
                i += 1
        return out

    def train(self, text, n_merges):
        ids = list(text.encode('utf-8'))
        self.merges = []
        self.vocab = {i: bytes([i]) for i in range(256)}
        for k in range(n_merges):
            counts = {}
            for pair in zip(ids, ids[1:]):
                counts[pair] = counts.get(pair, 0) + 1
            if not counts:
                break
