def near_duplicates(docs, threshold):
    sets = [{d[i:i + 5] for i in range(len(d) - 4)} for d in docs]
    pairs = []
    for i in range(len(docs)):
        for j in range(i + 1, len(docs)):
            a, b = sets[i], sets[j]
            if a and b and len(a & b) / len(a | b) >= threshold:
                pairs.append([i, j])
    return pairs

